<?php
require_once __DIR__.'/../includes/config.php';
if(session_status()===PHP_SESSION_NONE)session_start();
if(empty($_SESSION['admin_id']) && empty($_SESSION['admin_logged_in'])){header('Location: admin-login.php');exit;}
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function table_exists($db,$t){$t=$db->real_escape_string($t);$r=$db->query("SHOW TABLES LIKE '$t'");return $r&&$r->num_rows>0;}
$msg='';$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 $id=(int)($_POST['payment_id']??0);$action=$_POST['payment_action']??'';
 if($id>0 && in_array($action,['verify','reject','refund'],true) && table_exists($conn,'order_payments')){
  $status=$action==='verify'?'paid':($action==='reject'?'failed':'refunded');
  $s=$conn->prepare("UPDATE order_payments SET status=?, paid_at=CASE WHEN ?='paid' THEN COALESCE(paid_at,CURRENT_TIMESTAMP) ELSE paid_at END WHERE id=? LIMIT 1");
  if($s){$s->bind_param('ssi',$status,$status,$id);if($s->execute())$msg='Payment status updated successfully.';else$err='Unable to update payment.';$s->close();}
 }
}
$rows=[];$summary=['pending'=>0,'paid'=>0,'failed'=>0,'refunded'=>0];
if(table_exists($conn,'order_payments')){
 $q=$conn->query("SELECT p.id,p.order_id,p.method,p.status,p.amount,p.transaction_reference,p.paid_at,p.created_at,o.order_number,u.full_name AS customer_name,u.phone AS customer_phone,r.name AS restaurant_name FROM order_payments p LEFT JOIN orders o ON o.id=p.order_id LEFT JOIN users u ON u.id=o.user_id LEFT JOIN restaurants r ON r.id=o.restaurant_id ORDER BY p.created_at DESC");
 if($q)while($r=$q->fetch_assoc()){$rows[]=$r;if(isset($summary[$r['status']]))$summary[$r['status']]++;}
}else{$err='order_payments table is missing. Import the business upgrade SQL first.';}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Payment Verification - Humsafar</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"><style>body{margin:0;background:#f7f7f9;font-family:Segoe UI,Arial;color:#222}.page{margin-left:218px;padding:30px}.wrap{max-width:1250px;margin:auto}h1{font-size:29px;margin:0;font-weight:900}.sub{color:#777}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:20px 0}.card{background:#fff;border:1px solid #eee;border-radius:13px;padding:18px}.num{font-size:25px;font-weight:900}.label{font-size:11px;color:#777;font-weight:700}.tablebox{background:#fff;border:1px solid #eee;border-radius:14px;overflow:auto}table{width:100%;border-collapse:collapse;min-width:980px}th,td{padding:13px;border-bottom:1px solid #eee;text-align:left;font-size:12px}th{background:#faf5f7;font-size:10px;text-transform:uppercase;color:#777}.badge{padding:5px 8px;border-radius:20px;font-size:10px;font-weight:800}.pending{background:#fff4d8;color:#916500}.paid{background:#e7f8ed;color:#18733b}.failed{background:#ffe9ed;color:#a4002b}.refunded{background:#eee;color:#555}.btn{border:0;border-radius:7px;padding:7px 9px;font-size:10px;font-weight:800;cursor:pointer;margin:2px}.verify{background:#e7f8ed;color:#18733b}.reject{background:#ffe9ed;color:#a4002b}.refund{background:#eee;color:#555}.msg{padding:11px;border-radius:8px;background:#eaf8ef;color:#176c36;margin:15px 0}.err{background:#fff0f3;color:#a0002d}.empty{padding:30px;text-align:center;color:#888}@media(max-width:900px){.page{margin-left:0}.cards{grid-template-columns:2fr 2fr}}</style></head><body><?php include __DIR__.'/admin-sidebar.php';?><main class="page"><div class="wrap"><h1><i class="fa-solid fa-credit-card"></i> Payment Verification</h1><p class="sub">Review customer payments and verify, reject or refund them from one place.</p><?php if($msg):?><div class="msg"><?=h($msg)?></div><?php endif;?><?php if($err):?><div class="msg err"><?=h($err)?></div><?php endif;?><div class="cards"><div class="card"><div class="num"><?=$summary['pending']?></div><div class="label">Pending Verification</div></div><div class="card"><div class="num"><?=$summary['paid']?></div><div class="label">Verified / Paid</div></div><div class="card"><div class="num"><?=$summary['failed']?></div><div class="label">Rejected</div></div><div class="card"><div class="num"><?=$summary['refunded']?></div><div class="label">Refunded</div></div></div><div class="tablebox"><table><thead><tr><th>Order</th><th>Customer</th><th>Restaurant</th><th>Method</th><th>Amount</th><th>Reference</th><th>Status</th><th>Date</th><th>Action</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="9" class="empty">No payment records found.</td></tr><?php else:foreach($rows as $r):?><tr><td><b>#<?=h($r['order_number']?:$r['order_id'])?></b></td><td><?=h($r['customer_name'])?><br><small><?=h($r['customer_phone'])?></small></td><td><?=h($r['restaurant_name'])?></td><td><?=h(strtoupper($r['method']))?></td><td><b>PKR <?=number_format((float)$r['amount'],2)?></b></td><td><?=h($r['transaction_reference']?:'—')?></td><td><span class="badge <?=h($r['status'])?>"><?=h(ucfirst($r['status']))?></span></td><td><?=h($r['created_at'])?></td><td><?php if($r['status']==='pending'):?><form method="post" style="display:inline"><input type="hidden" name="payment_id" value="<?=h($r['id'])?>"><button class="btn verify" name="payment_action" value="verify">Verify</button><button class="btn reject" name="payment_action" value="reject">Reject</button></form><?php elseif($r['status']==='paid'):?><form method="post" style="display:inline"><input type="hidden" name="payment_id" value="<?=h($r['id'])?>"><button class="btn refund" name="payment_action" value="refund">Refund</button></form><?php else:?>—<?php endif;?></td></tr><?php endforeach;endif;?></tbody></table></div></div></main></body></html>